document.querySelectorAll('[data-t]').forEach(el=>translations.en[el.dataset.t]=el.innerHTML);
const state={lang:'ar',program:'swimming',filter:'all',route:'home'};
const text=(en,ar)=>state.lang==='en'?en:ar;
const icons={swimming:'<path d="M20 87c12-12 18 12 30 0s18 12 30 0 18 12 30 0 18 12 30 0M20 101c12-12 18 12 30 0s18 12 30 0 18 12 30 0 18 12 30 0"/><circle cx="112" cy="59" r="10"/><path d="m44 75 35-20-24-24 15-11 34 30M79 55l18 21"/>',taekwondo:'<circle cx="83" cy="25" r="11"/><path d="m77 42-18 25 27 17 26-14M77 42l26 6 16-19M77 42 49 34 29 47M59 67l-23 26M74 55l10 14M62 63l18 11M22 108h117"/>',robotics:'<rect x="43" y="34" width="76" height="56" rx="10"/><path d="M81 34V20M33 49v26M129 49v26M63 90v13M99 90v13M67 74h28"/><circle cx="65" cy="54" r="4"/><circle cx="98" cy="54" r="4"/><circle cx="81" cy="16" r="4"/>',trip:'<path d="M25 100 62 37l27 43 20-30 30 50Z"/><path d="M49 59l13 8 13-8M101 64l9 8 9-8"/><circle cx="115" cy="25" r="10"/>'};
const catalog={swimming:{en:'Swimming',ar:'السباحة',price:600,category:'sport',enDesc:'Make a splash. Explore confidence in the water.',arDesc:'مساحة للحركة واكتشاف الثقة في الماء.'},taekwondo:{en:'Taekwondo',ar:'التايكوندو',price:600,category:'sport',enDesc:'Discover a new discipline, one movement at a time.',arDesc:'اكتشف رياضة جديدة، خطوة بعد خطوة.'},robotics:{en:'Robotics',ar:'الروبوتات',price:900,category:'technology',enDesc:'A space for curious minds and big ideas.',arDesc:'مساحة للعقول الفضولية والأفكار الكبيرة.'},trip:{en:'School science trip',ar:'رحلة مدرسية علمية',price:150,category:'trip'}};
const art=id=>`<div class="activity-art ${id}"><svg viewBox="0 0 160 120" aria-hidden="true">${icons[id]}</svg></div>`;
const price=n=>new Intl.NumberFormat('en-SA').format(n);
function renderCards(){
 $('activity-grid').innerHTML=Object.entries(catalog).filter(([id,p])=>id!=='trip'&&(state.filter==='all'||p.category===state.filter)).map(([id,p],i)=>`<article class="activity-card">${art(id)}<div class="card-body"><span class="card-category">${p.category==='sport'?text('SPORT & MOVEMENT','رياضة وحركة'):text('SCIENCE & TECHNOLOGY','علوم وتقنية')}</span><h2>${p[state.lang]}</h2><p>${p[state.lang==='en'?'enDesc':'arDesc']}</p><div class="card-price"><div><strong>${price(p.price)} <span class="currency">${text('SAR','ر.س')}</span></strong><small>${text('Example amount','مبلغ توضيحي')}</small></div><a class="card-link" href="#enroll/${id}">${text('Choose activity','اختر النشاط')} <span>${text('→','←')}</span></a></div></div></article>`).join('');
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter))});
}
function renderStudent(){const name=$('student-name').value.trim(),id=$('student-id').value.trim();$('student-name').setCustomValidity(name&&(!/[\u0621-\u064a]/.test(name)||/[A-Za-z]/.test(name))?text('Enter the student name in Arabic.','أدخل اسم الطالب بالعربية.'): '');$('preview-name').textContent=name||text('Your student','الطالب المشارك');$('preview-id').textContent=id?text('Student ID: ','الرقم المدرسي: ')+id:'';document.querySelector('.student-preview').hidden=!name;document.querySelector('.student-complete-top').hidden=!name}
function renderOrder(){const p=catalog[state.program];$('order-title').textContent=p[state.lang];$('order-amount').textContent=price(p.price);$('plan-note').textContent=state.program==='trip'?text('One payment of SAR 150. Illustrative trip only.','دفعة واحدة 150 ر.س. رحلة توضيحية فقط.'):text(`SAR ${price(p.price*.95)} in full, or split into 2, 3 or 4 payments.`,`دفع كامل ${price(p.price*.95)} ر.س، أو قسّم المبلغ على دفعتين أو 3 أو 4 دفعات.`);renderStudent()}
function translate(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>{el.innerHTML=translations[state.lang][el.dataset.t]||translations.en[el.dataset.t]});document.querySelectorAll('[data-language]').forEach(b=>b.textContent=state.lang==='en'?'العربية':'English');$('student-name').placeholder=text('Full name','الاسم الكامل');$('student-id').placeholder=text('Student ID','الرقم المدرسي');$('menu-toggle').setAttribute('aria-label',text('Open navigation','فتح القائمة'));document.querySelector('.pay-button>span:last-child').textContent=state.lang==='ar'?'←':'→';renderCards();renderOrder();updateTitle()}
function updateTitle(){document.title=(state.route==='enroll'?text('Student details','بيانات الطالب'):state.route==='payment'?text('Payment','الدفع'):state.route==='activities'?text('Activities','الأنشطة'):text('Riyadh International','فرع الرياض العالمي'))+' | '+text('Al Andalus Schools','مدارس الأندلس')}
let previousRoute='';
function route(){const segments=location.hash.replace(/^#/,'').split('/');let page=segments[0]||'home';if(page==='programs')page='activities';if(page==='enroll'&&segments[1]&&catalog[segments[1]])state.program=segments[1];if(!['home','about','life','contact','activities','enroll','payment'].includes(page))page='home';if(page==='payment'&&!$('student-form').checkValidity()){location.replace('#enroll/'+state.program);return}state.route=page;const checkout=page==='enroll'||page==='payment';$('school-shell').hidden=checkout;$('enrollment-page').hidden=!checkout;$('payment-placeholder').hidden=page==='payment';$('payment-surface').hidden=page!=='payment';$('student-editor').hidden=page==='payment';$('student-complete').hidden=false;$('external-checkout').hidden=page!=='payment';$('home-page').hidden=page==='activities';$('activities-page').hidden=page!=='activities';document.body.classList.toggle('payment-mode',page==='payment');document.body.classList.toggle('checkout-mode',checkout);$('enrollment-page').classList.toggle('payment-ready',page==='payment');document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('site-nav').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');renderOrder();updateTitle();if(page==='payment'){if(previousRoute!=='payment')openPayment()}else{$('checkout-frame').removeAttribute('src');$('payment-loading').hidden=false;if(['about','life','contact'].includes(page)){requestAnimationFrame(()=>$(page).scrollIntoView({behavior:'smooth'}))}else window.scrollTo({top:0,behavior:'instant'});}previousRoute=page}
function openPayment(){const raw=state.program==='trip'?window.TRIP_CHECKOUT:window.PROGRAM_CHECKOUT?.[state.program];if(!raw)return;const url=new URL(raw);if(url.protocol!=='https:'||url.origin!=='https://staging.billing.streampay.sa'||url.searchParams.get('organization_id')!=='a5ba27c4-685e-43f6-b6ce-1482cca040aa')return;url.searchParams.set('embed','true');url.searchParams.set('language','ar');url.searchParams.set('name',$('parent-name').value.trim());url.searchParams.set('phone','+966'+$('parent-phone').value.replace(/^0/,''));$('checkout-frame').style.height='100%';$('payment-loading').hidden=false;$('external-checkout').href=url.href;$('loading-fallback').href=url.href;$('checkout-frame').src=url.href}
$('checkout-frame').addEventListener('load',()=>{if($('checkout-frame').hasAttribute('src'))$('payment-loading').hidden=true});
// Only the active Stream frame can request a resize or verified payment handoff.
const streamOrigins=new Set(['https://staging.billing.streampay.sa','https://streampay.sa','https://stream-embed.streampay.sa']);
window.addEventListener('message',event=>{
 const frame=$('checkout-frame');
 if(event.source!==frame.contentWindow||!streamOrigins.has(event.origin)||!event.data||typeof event.data!=='object')return;
 if(event.data.type==='stream:ready')$('payment-loading').hidden=true;
 if(event.data.type==='stream:resize'){
  const height=Number(event.data.data?.height??event.data.height);
  if(Number.isFinite(height)&&height>=200&&height<=10000){$('payment-surface').dataset.contentHeight=String(Math.ceil(height));frame.style.height='100%';frame.setAttribute('scrolling',height>$('payment-surface').clientHeight+4?'auto':'no')}
 }
 if(event.data.type==='stream:redirect'){
  try{
   const next=new URL(event.data.url);
   if(next.protocol!=='https:'||next.username||next.password||next.port)throw new Error();
   if(streamOrigins.has(next.origin)){next.searchParams.delete('embed');next.searchParams.delete('embed_domain');next.searchParams.set('language','ar')}
   else if(next.origin===window.location.origin&&next.pathname==='/success.html'){}
   else if(next.origin!=='https://api.moyasar.com'||next.hash||!(/^\/v1\/transaction_auths\/[A-Za-z0-9_-]+(?:\/form)?$/.test(next.pathname)||/^\/v1\/card_auth\/[0-9a-f-]{36}\/(?:prepare|acs_emulator)$/.test(next.pathname)))throw new Error();
   // The official embed SDK hands authentication to the top-level window.
   // Stream then displays its confirmed result and official receipt outside the iframe.
   window.location.assign(next.href);
  }catch{$('payment-loading').hidden=false;$('payment-loading').querySelector('p').textContent=text('Continue in the secure payment window.','تابع في نافذة الدفع الآمنة.')}
 }
});
$('student-form').addEventListener('submit',e=>{e.preventDefault();for(const id of ['student-name','student-id','parent-name','parent-phone']){const input=$(id);input.value=input.value.trim()}if(!$('student-form').reportValidity())return;renderStudent();location.hash='payment'});
for(const id of ['student-name','student-id'])$(id).addEventListener('input',renderStudent);
$('parent-name').addEventListener('input',()=>{$('parent-name').setCustomValidity($('parent-name').value.trim()&&(!/[\u0621-\u064a]/.test($('parent-name').value)||/[A-Za-z]/.test($('parent-name').value))?'أدخل اسم ولي الأمر بالعربية.':'')});
$('parent-phone').addEventListener('input',()=>{$('parent-phone').value=$('parent-phone').value.replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[^0-9]/g,'')});
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{state.lang=state.lang==='en'?'ar':'en';translate()}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;renderCards()}));
$('menu-toggle').addEventListener('click',()=>{$('site-nav').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String($('site-nav').classList.contains('open')))});
$('stories').addEventListener('click',()=>{$('stories-dialog').showModal();document.body.classList.add('dialog-open')});
$('close-stories').addEventListener('click',()=>$('stories-dialog').close());
$('stories-dialog').addEventListener('close',()=>document.body.classList.remove('dialog-open'));
$('story-trip').addEventListener('click',()=>{$('stories-dialog').close();location.hash='enroll/trip'});
$('reset').addEventListener('click',()=>{$('student-form').reset();state.lang='ar';state.program='swimming';state.filter='all';$('stories-dialog').close();translate();location.hash='home';route()});
for(const id of ['student-name','student-id','parent-name','parent-phone']){const input=$(id);input.addEventListener('invalid',()=>{if(input.validity.valueMissing)input.setCustomValidity(text('Please complete this field.','يرجى تعبئة هذا الحقل.'));else if(id==='parent-phone'&&input.validity.patternMismatch)input.setCustomValidity(text('Enter a Saudi mobile number starting with 05 or 5.','أدخل رقم جوال سعودي يبدأ بـ 05 أو 5.'))});input.addEventListener('input',()=>{if(input.validity.customError&&!['student-name','parent-name'].includes(id))input.setCustomValidity('')})}
window.addEventListener('hashchange',route);translate();route();
